import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ClassicClockProps = Record<string, any>;

const ClassicClock: React.FC<ClassicClockProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 10,
  clockFaceColor = "#f9f9f9",
  hourHandColor = "#2c3e50",
  minuteHandColor = "#7f8c8d",
  secondHandColor = "#e74c3c",
  markColor = "#bdc3c7",
  textColor = "#34495e",
  clockRadius = 300,
  startHour = 10,
  startMinute = 10,
  showNumbers = true,
  showSeconds = true,
  smoothSeconds = true,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser Safety for Background
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Time Calculations
  // Calculate total seconds elapsed since start of animation
  const framesElapsed = frame;
  const secondsElapsed = framesElapsed / fps;

  // Calculate initial time in seconds (from 12:00)
  const initialSeconds = (startHour % 12) * 3600 + startMinute * 60;
  
  // Total absolute time in seconds for the clock display
  const totalClockSeconds = initialSeconds + secondsElapsed;

  // Rotation Angles
  // Hour hand: 360 deg / 12 hours = 30 deg/hour. 
  // It also moves based on minutes/seconds.
  // 12 hours = 43200 seconds.
  const hourAngle = (totalClockSeconds / 43200) * 360;

  // Minute hand: 360 deg / 60 min = 6 deg/min.
  // 1 hour = 3600 seconds.
  const minuteAngle = ((totalClockSeconds % 3600) / 3600) * 360;

  // Second hand: 360 deg / 60 sec = 6 deg/sec.
  // We handle smooth vs ticking here.
  const secondAngleRaw = totalClockSeconds % 60;
  const secondAngle = smoothSeconds 
    ? (secondAngleRaw / 60) * 360 
    : Math.floor(secondAngleRaw) * 6;

  // Layout Calculations
  const centerX = width / 2;
  const centerY = height / 2;
  const strokeWidth = clockRadius * 0.02;

  // Generate ticks
  const ticks = React.useMemo(() => {
    return Array.from({ length: 60 }).map((_, i) => {
      const isHour = i % 5 === 0;
      const angle = (i * 6) * (Math.PI / 180);
      const tickLen = isHour ? clockRadius * 0.15 : clockRadius * 0.07;
      const tickStroke = isHour ? strokeWidth * 1.5 : strokeWidth * 0.5;
      
      const x1 = centerX + (clockRadius - tickLen) * Math.sin(angle);
      const y1 = centerY - (clockRadius - tickLen) * Math.cos(angle);
      const x2 = centerX + (clockRadius - strokeWidth) * Math.sin(angle);
      const y2 = centerY - (clockRadius - strokeWidth) * Math.cos(angle);

      return (
        <line
          key={`tick-${i}`}
          x1={x1}
          y1={y1}
          x2={x2}
          y2={y2}
          stroke={markColor}
          strokeWidth={tickStroke}
          strokeLinecap="round"
        />
      );
    });
  }, [centerX, centerY, clockRadius, markColor, strokeWidth]);

  // Generate numbers
  const numbers = React.useMemo(() => {
    if (!showNumbers) return null;
    return Array.from({ length: 12 }).map((_, i) => {
      const num = i + 1; // 1-12
      const angle = (num * 30) * (Math.PI / 180);
      const dist = clockRadius * 0.72; // Position numbers slightly inward
      const x = centerX + dist * Math.sin(angle);
      const y = centerY - dist * Math.cos(angle);
      
      return (
        <text
          key={`num-${num}`}
          x={x}
          y={y}
          fill={textColor}
          fontSize={clockRadius * 0.18}
          fontFamily="Inter"
          fontWeight="600"
          textAnchor="middle"
          dominantBaseline="middle"
        >
          {num}
        </text>
      );
    });
  }, [showNumbers, centerX, centerY, clockRadius, textColor]);

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        {/* Drop Shadow Filter */}
        <defs>
          <filter id="shadow" x="-50%" y="-50%" width="200%" height="200%">
            <feDropShadow dx="0" dy={clockRadius * 0.02} stdDeviation={clockRadius * 0.03} floodOpacity="0.2" />
          </filter>
        </defs>

        {/* Clock Face */}
        <circle
          cx={centerX}
          cy={centerY}
          r={clockRadius}
          fill={clockFaceColor}
          filter="url(#shadow)"
        />
        
        {/* Border Ring */}
        <circle
          cx={centerX}
          cy={centerY}
          r={clockRadius}
          fill="none"
          stroke={markColor}
          strokeWidth={strokeWidth}
          opacity={0.1}
        />

        {/* Ticks and Numbers */}
        {ticks}
        {numbers}

        {/* Hour Hand */}
        <line
          x1={centerX}
          y1={centerY}
          x2={centerX}
          y2={centerY - clockRadius * 0.5}
          stroke={hourHandColor}
          strokeWidth={strokeWidth * 2.5}
          strokeLinecap="round"
          transform={`rotate(${hourAngle}, ${centerX}, ${centerY})`}
          style={{ transition: "none" }}
        />

        {/* Minute Hand */}
        <line
          x1={centerX}
          y1={centerY}
          x2={centerX}
          y2={centerY - clockRadius * 0.8}
          stroke={minuteHandColor}
          strokeWidth={strokeWidth * 1.5}
          strokeLinecap="round"
          transform={`rotate(${minuteAngle}, ${centerX}, ${centerY})`}
          style={{ transition: "none" }}
        />

        {/* Second Hand */}
        {showSeconds && (
          <g transform={`rotate(${secondAngle}, ${centerX}, ${centerY})`} style={{ transition: "none" }}>
            {/* Main red hand */}
            <line
              x1={centerX}
              y1={centerY + clockRadius * 0.15} // Slight overhang
              x2={centerX}
              y2={centerY - clockRadius * 0.85}
              stroke={secondHandColor}
              strokeWidth={strokeWidth * 0.5}
              strokeLinecap="round"
            />
            {/* Center dot for second hand */}
            <circle
              cx={centerX}
              cy={centerY}
              r={strokeWidth * 1.2}
              fill={secondHandColor}
            />
          </g>
        )}

        {/* Center Pin (Covering Hour/Minute joins) */}
        {!showSeconds && (
           <circle
           cx={centerX}
           cy={centerY}
           r={strokeWidth * 2}
           fill={hourHandColor}
         />
        )}
      </svg>
    </AbsoluteFill>
  );
};

export default ClassicClock;